class Solution {
  public int numberOfSubstrings(String s) {
    int n = s.length(), m = 0;
    int[] zeroAt = new int[n];
    int[] nextZero = new int[n + 1]; // index into zeroAt of the first zero at or after i
    for (int i = 0; i < n; i++) if (s.charAt(i) == '0') zeroAt[m++] = i;
    int cursor = m;
    nextZero[n] = m;
    for (int i = n - 1; i >= 0; i--) {
      if (s.charAt(i) == '0') cursor--;
      nextZero[i] = cursor;
    }
    long answer = 0;
    for (int start = 0; start < n; start++) {
      int first = nextZero[start];
      for (int zeros = 0; (long) zeros * zeros + zeros <= n - start; zeros++) {
        // end positions with exactly `zeros` zeros
        int lo = zeros == 0 ? start : (first + zeros - 1 < m ? zeroAt[first + zeros - 1] : -1);
        if (lo < 0) break;
        int hi = first + zeros < m ? zeroAt[first + zeros] - 1 : n - 1;
        // ones = length - zeros >= zeros^2
        lo = Math.max(lo, start + zeros * zeros + zeros - 1);
        if (lo <= hi) answer += hi - lo + 1;
      }
    }
    return (int) answer;
  }
}
